using DessertKitchen.Domain;
using DessertKitchen.Infrastructure;
using Xunit;
namespace DessertKitchen.Tests;
public class SalesTests {
 static string Id()=>Guid.NewGuid().ToString("N");
 static Store Kitchen(){var s=new Store(Path.Combine(Path.GetTempPath(),"sales-tests",Id(),"k.db"));Seed.Run(s);var b=s.DefaultBusiness();s.SaveBusiness(b with{Channels=b.Channels.Select(c=>c with{CommissionConfigured=true,CommissionPercent=c.Id=="direct"?0:30,FeeVatPercent=c.Id=="direct"?0:20}).ToList()});return s;}
 static OrderInput Basket(string channel="direct")=>new(Id(),Id(),0,channel,[new("brownie",2,6.95m),new("lemon-pot",1,5.95m)]);
 static void Stock(Store s,string id,decimal q)=>s.AddExistingStock(new(Id(),"recipe",id,q,"each","home",AllergenRules.Today(),"test",DateReviewed:true,DateEvidence:"Test checked",TotalCost:q,ValuationStatus:"known",Notes:"Synthetic stock",RecipeVersion:1));
 [Fact] public void OrderTotalsStockRetryRefundAndHistoricalFees(){var s=Kitchen();Stock(s,"brownie",9);Stock(s,"lemon-pot",3);var input=Basket("deliveroo");var o=s.SaveOrder(input);Assert.Equal(19.85m,o.Total);Assert.Equal(7.15m,o.ExpectedFees);Assert.Equal(o.Id,s.SaveOrder(input).Id);Assert.Single(s.Orders());var before=s.StockMovements().Count;var action=new OrderAction(Id(),o.Id,o.Revision,"complete","home");o=s.ActOrder(action);s.ActOrder(action);Assert.Equal(before+2,s.StockMovements().Count);Assert.Equal(7,s.StockMovements().Where(m=>s.StockLots().First(l=>l.Id==m.LotId).ItemId=="brownie").Sum(m=>m.Quantity));Assert.Equal(3,o.Lines.Sum(l=>l.InventoryCost));var b=s.CurrentBusiness();s.SaveBusiness(b with{Channels=b.Channels.Select(c=>c with{CommissionPercent=50}).ToList(),Products=[new("brownie",b.Channels.Select(c=>new ProductChannel(c.Id,99)).ToList())]});Assert.Equal(7.15m,s.Orders()[0].ExpectedFees);Assert.Equal(6.95m,s.Orders()[0].Lines[0].Price);Assert.Equal(30,s.Orders()[0].ChannelSnapshot!.CommissionPercent);var count=s.StockMovements().Count;s.ActOrder(new(Id(),o.Id,o.Revision,"refund",Amount:19.85m,Reason:"Customer refunded"));Assert.Equal(count,s.StockMovements().Count);Assert.Equal(19.85m,s.Orders()[0].Refunds);}
 [Fact] public void CancellationShortageAndDuplicateReferencesAreSafe(){var s=Kitchen();var input=Basket() with{Reference="external-1"};var o=s.SaveOrder(input);Assert.Throws<ValidationException>(()=>s.SaveOrder(input with{OperationId=Id(),Id=Id()}));Assert.Throws<ValidationException>(()=>s.ActOrder(new(Id(),o.Id,o.Revision,"complete","home")));Assert.Empty(s.StockMovements());Assert.Equal("received",s.Orders()[0].Status);o=s.ActOrder(new(Id(),o.Id,o.Revision,"cancel",Reason:"Changed mind"));Assert.Empty(s.StockMovements());Assert.Equal("cancelled",o.Status);Assert.Throws<ValidationException>(()=>s.ActOrder(new(Id(),o.Id,o.Revision,"complete","home")));}
 [Fact] public void UnknownFeesStayUnknownAndDraftsRequireConfirmation(){var s=Kitchen();var b=s.CurrentBusiness();s.SaveBusiness(b with{Channels=b.Channels.Select(c=>c with{CommissionConfigured=false}).ToList()});var o=s.SaveOrder(Basket("uber") with{Confirm=false});Assert.Null(o.ExpectedFees);Assert.Throws<ValidationException>(()=>s.ActOrder(new(Id(),o.Id,o.Revision,"complete","home")));}
 [Fact] public void MadeToOrderUsesExplicitProductionOnlyOnce(){var s=Kitchen();var p=new ProductionInput(Id(),"brownie",1,2,2,"home","home",AllergenRules.Today(),"ORDER-PREP",Mode:"made-to-order",DateReviewed:true,DateEvidence:"Checked");foreach(var r in s.Requirements("brownie",1,2))s.AddExistingStock(new(Id(),"ingredient",r.ItemId,r.Quantity,r.Unit,"home",AllergenRules.Today(),"test",DateReviewed:true,DateEvidence:"Checked",TotalCost:1,ValuationStatus:"known",Notes:"Test"));s.Produce(p);var count=s.StockMovements().Count;var o=s.SaveOrder(new(Id(),Id(),0,"direct",[new("brownie",2,6.95m)]));o=s.ActOrder(new(Id(),o.Id,o.Revision,"complete","home",new(){["brownie"]=p.OperationId}));Assert.Equal(count,s.StockMovements().Count);Assert.Equal("completed",o.Status);var other=s.SaveOrder(new(Id(),Id(),0,"direct",[new("brownie",2,6.95m)]));Assert.Throws<ValidationException>(()=>s.ActOrder(new(Id(),other.Id,other.Revision,"complete","home",new(){["brownie"]=p.OperationId})));Assert.Throws<ValidationException>(()=>s.ReverseStock(new(Id(),p.OperationId,"Cannot reverse consumed preparation")));}

 static SalesImportInput Report(string csv)=>new(Id(),"deliveroo",csv,new(){["reference"]="ref",["date"]="date",["gross"]="gross",["commission"]="fees",["otherFees"]="other",["refund"]="refund",["net"]="net"},true);
 [Fact] public void CsvImportIsFinancialOnlyDeduplicatedAndConflictsVisible(){var s=Kitchen();var input=Report("ref,date,gross,fees,other,refund,net\nA,2026-01-01,300,108,7,10,175");Assert.Equal("new",s.PreviewSalesImport(input)[0].Status);s.ConfirmSalesImport(input);s.ConfirmSalesImport(input);Assert.Single(s.Orders());Assert.Empty(s.StockMovements());Assert.Equal("duplicate",s.PreviewSalesImport(input)[0].Status);Assert.Equal("conflict",s.PreviewSalesImport(input with{Csv=input.Csv.Replace("300","301")})[0].Status);Assert.Equal("incomplete",s.PreviewSalesImport(input with{Csv="ref,date,gross,fees,other,refund,net\nB,invalid,300,108,7,10,175"})[0].Status);Assert.Throws<ValidationException>(()=>s.ParseSalesCsv("ref,ref\n1,2"));}
 [Fact] public void PayoutsShowDifferencesAndSupportPartialReceiptsAndCorrections(){var s=Kitchen();s.ConfirmSalesImport(Report("ref,date,gross,fees,other,refund,net\nA,2026-01-01,300,108,7,10,175"));var o=s.Orders()[0];var p=new PayoutInput(Id(),"deliveroo","P1",AllergenRules.Today(),[o.Id],170);var result=s.RecordPayout(p);Assert.Equal(175,result.Expected);Assert.Equal(5,result.Difference);Assert.Equal(System.Text.Json.JsonSerializer.Serialize(result),System.Text.Json.JsonSerializer.Serialize(s.RecordPayout(p)));var second=s.RecordPayout(p with{Id=Id(),Reference="P2",Actual=5});Assert.Equal("Reconciled",second.Status);Assert.Equal("settled",s.Orders()[0].PaymentStatus);var correction=s.RecordPayout(p with{Id=Id(),Reference="P1 correction",Actual=169,Corrects=p.Id,Notes="Correct bank amount"});Assert.Equal(1,correction.Difference);Assert.Equal(3,s.Payouts().Count);Assert.Empty(s.StockMovements());}

 [Fact] public void ReportingAndBackupKeepTransactionsSeparateFromForecasts(){var s=Kitchen();Stock(s,"brownie",9);Stock(s,"lemon-pot",3);var before=System.Text.Json.JsonSerializer.Serialize(s.CurrentBusiness());var o=s.SaveOrder(Basket());o=s.ActOrder(new(Id(),o.Id,o.Revision,"complete","home"));s.ActOrder(new(Id(),o.Id,o.Revision,"refund",Amount:1,Reason:"Partial refund"));var r=System.Text.Json.JsonSerializer.SerializeToElement(s.SalesReport(AllergenRules.Today(),AllergenRules.Today()),Store.Json);Assert.Equal(18.85m,r.GetProperty("revenue").GetDecimal());Assert.Equal(1,r.GetProperty("orders").GetInt32());Assert.Equal(2,r.GetProperty("products").GetArrayLength());Assert.Equal(before,System.Text.Json.JsonSerializer.Serialize(s.CurrentBusiness()));var path=Path.Combine(Path.GetTempPath(),Id()+".db");File.WriteAllBytes(path,s.Backup());Store.Restore(path,path+".restored");var restored=new Store(path+".restored");Assert.Equal(System.Text.Json.JsonSerializer.Serialize(s.Orders()),System.Text.Json.JsonSerializer.Serialize(restored.Orders()));Assert.Equal(s.StockMovements().Count,restored.StockMovements().Count);}
 [Fact] public void StaleEditsAndFailedMultiLineFulfilmentAreAtomic(){var s=Kitchen();Stock(s,"brownie",9);var o=s.SaveOrder(Basket());var count=s.StockMovements().Count;Assert.Throws<ValidationException>(()=>s.ActOrder(new(Id(),o.Id,o.Revision,"complete","home")));Assert.Equal(count,s.StockMovements().Count);s.ActOrder(new(Id(),o.Id,o.Revision,"ready"));Assert.Throws<ConflictException>(()=>s.ActOrder(new(Id(),o.Id,o.Revision,"cancel",Reason:"Stale")));}

 [Fact] public void PopulatedBackupMigrationPreservesAllExistingRows(){var source=Environment.GetEnvironmentVariable("KITCHEN_MIGRATION_SOURCE");if(string.IsNullOrEmpty(source))return;var path=Path.Combine(Path.GetTempPath(),"sales-migration",Id(),"copy.db");Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.Copy(source,path);Dictionary<string,string> Snapshot(){using var db=new Microsoft.Data.Sqlite.SqliteConnection("Data Source="+path);db.Open();using var cmd=db.CreateCommand();cmd.CommandText="SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE 'sales_%' AND name<>'schema_migrations'";using var reader=cmd.ExecuteReader();var tables=new List<string>();while(reader.Read())tables.Add(reader.GetString(0));reader.Close();var result=new Dictionary<string,string>();foreach(var table in tables){cmd.CommandText="SELECT * FROM "+table+" ORDER BY rowid";using var rows=cmd.ExecuteReader();var values=new List<object[]>();while(rows.Read()){var v=new object[rows.FieldCount];rows.GetValues(v);values.Add(v);}result[table]=System.Text.Json.JsonSerializer.Serialize(values);}return result;}var before=Snapshot();var store=new Store(path);var after=Snapshot();foreach(var pair in before)Assert.Equal(pair.Value,after[pair.Key]);Assert.Empty(store.Orders());Assert.Empty(store.Payouts());Assert.Single(Directory.GetFiles(Path.Combine(Path.GetDirectoryName(path)!,"backups"),"before-migration-5-*.db"));}
 [Fact] public async Task SalesEndpointsRequireOwnerAndImmutableAuditRejectsDeletion(){using var factory=new KitchenFactory();using var client=factory.CreateClient();Assert.Equal(System.Net.HttpStatusCode.Unauthorized,(await client.GetAsync("/api/sales/orders")).StatusCode);var s=Kitchen();var o=s.SaveOrder(Basket());using var db=s.Open();using var cmd=db.CreateCommand();cmd.CommandText="DELETE FROM sales_events";Assert.Throws<Microsoft.Data.Sqlite.SqliteException>(()=>cmd.ExecuteNonQuery());}

 [Fact] public void ReportedPayoutFeesResolveUnknownBalancesAndLaterRefundsRemainVisible(){var s=Kitchen();s.ConfirmSalesImport(Report("ref,date,gross,fees,other,refund,net\nA,2026-01-01,300,,,,"));var o=s.Orders()[0];var p=new PayoutInput(Id(),"deliveroo","P",AllergenRules.Today(),[o.Id],192,Commission:108);s.RecordPayout(p);var report=System.Text.Json.JsonSerializer.SerializeToElement(s.SalesReport(new(2026,1,1),AllergenRules.Today()),Store.Json);Assert.Equal(0,report.GetProperty("awaitingPayout").GetDecimal());o=s.Orders()[0];s.ActOrder(new(Id(),o.Id,o.Revision,"refund",Amount:10,Reason:"Later refund"));var view=System.Text.Json.JsonSerializer.SerializeToElement(s.PayoutView(),Store.Json);Assert.Equal(-10,view.GetProperty("groups")[0].GetProperty("difference").GetDecimal());Assert.NotEqual("Reconciled",view.GetProperty("groups")[0].GetProperty("status").GetString());}
}
